import type { Task, Filter } from '../types';

const STATE_KEY = 'workshop.todo.state';
const LEGACY_TASKS_KEY = 'workshop.todo.tasks';
const LEGACY_FILTER_KEY = 'workshop.todo.filter';

type PersistedState = { tasks: Task[]; filter: Filter };

function readState(): PersistedState {
  try {
    const raw = localStorage.getItem(STATE_KEY);
    if (raw) return JSON.parse(raw) as PersistedState;
  } catch {
    /* fall through to the legacy path */
  }
  return migrateLegacy();
}

function migrateLegacy(): PersistedState {
  let tasks: Task[] = [];
  try {
    const raw = localStorage.getItem(LEGACY_TASKS_KEY);
    if (raw) tasks = JSON.parse(raw) as Task[];
  } catch {
    tasks = [];
  }
  const legacyFilter = localStorage.getItem(LEGACY_FILTER_KEY);
  const filter: Filter = legacyFilter === 'active' || legacyFilter === 'done' ? legacyFilter : 'all';
  const state = { tasks, filter };
  writeState(state);
  localStorage.removeItem(LEGACY_TASKS_KEY);
  localStorage.removeItem(LEGACY_FILTER_KEY);
  return state;
}

function writeState(state: PersistedState): void {
  localStorage.setItem(STATE_KEY, JSON.stringify(state));
}

export function loadTasks(): Task[] {
  return readState().tasks;
}

export function saveTasks(tasks: Task[]): void {
  writeState({ ...readState(), tasks });
}

export function loadFilter(): Filter {
  return readState().filter;
}

export function saveFilter(filter: Filter): void {
  writeState({ ...readState(), filter });
}

