// @vitest-environment jsdom
import { describe, it, expect, beforeEach } from 'vitest';
import { loadTasks, loadFilter, saveFilter } from './storage';

const STATE_KEY = 'workshop.todo.state';
const LEGACY_TASKS_KEY = 'workshop.todo.tasks';
const LEGACY_FILTER_KEY = 'workshop.todo.filter';

const task = { id: 1, label: 'buy milk', done: false, createdAt: 0 };

describe('storage migration', () => {
  beforeEach(() => localStorage.clear());

  it('returns an empty list when nothing is stored', () => {
    expect(loadTasks()).toEqual([]);
  });

  it('restores tasks saved under the legacy key', () => {
    localStorage.setItem(LEGACY_TASKS_KEY, JSON.stringify([task]));
    expect(loadTasks()).toEqual([task]);
  });

  it('restores the filter saved under the legacy key', () => {
    localStorage.setItem(LEGACY_FILTER_KEY, 'done');
    expect(loadFilter()).toBe('done');
  });

  it('writes through to the consolidated key', () => {
    saveFilter('active');
    expect(JSON.parse(localStorage.getItem(STATE_KEY)!).filter).toBe('active');
  });
});

